import{c as t,Q as a,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const l="/assets/DeInterleave-39.CLCNY7Rs.png",R=JSON.parse('{"title":"DeInterleave","description":"","frontmatter":{},"headers":[{"level":1,"title":"DeInterleave","slug":"deinterleave"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"定义原型","slug":"定义原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/数据重排/DeInterleave-52.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/数据重排/DeInterleave-52.md"}'),d={name:"api/SIMD-API/基础API/Reg矢量计算/数据重排/DeInterleave-52.md"};function r(i,e,p,o,c,g){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="deinterleave" tabindex="-1">DeInterleave <a class="header-anchor" href="#deinterleave" aria-label="Permalink to &quot;DeInterleave&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>给定源操作数寄存器张量srcReg0和srcReg1，将srcReg0和srcReg1中的元素解交织存入结果操作数dstReg0和dstReg1中。解交织排列方式如下图所示，其中每个方格代表一个元素：</p><p><img src="'+l+`" alt=""></p><h2 id="定义原型" tabindex="-1">定义原型 <a class="header-anchor" href="#定义原型" aria-label="Permalink to &quot;定义原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T = DefaultType, typename U&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void DeInterleave(U&amp; dstReg0, U&amp; dstReg1, U&amp; srcReg0, U&amp; srcReg1)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>目的操作数和源操作数的数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：bool/uint8_t/int8_t/uint16_t/int16_t/uint32_t/int32_t/uint64_t/int64_t/half/float/bfloat16_t</td></tr><tr><td>U</td><td>源操作数和目的操作数的RegTensor类型，例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要填写。</td></tr></tbody></table><p><strong>表 2</strong> 函数参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstReg0、dstReg1</td><td>输出</td><td>目的操作数。 类型为RegTensor。</td></tr><tr><td>srcReg0、srcReg1</td><td>输入</td><td>源操作数。 类型为RegTensor。 源操作数的数据类型需要与目的操作数保持一致。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>b64数据类型下仅支持RegTraitNumTwo。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void DeInterLeaveVF(__ubuf__ T* dst0Addr, __ubuf__ T* dst1Addr, __ubuf__ T* src0Addr, __ubuf__ T* src1Addr, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg0;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg1;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; dstReg0;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; dstReg1;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask = AscendC::Reg::CreateMask&lt;T, AscendC::Reg::MaskPattern::ALL&gt;();</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg0, src0Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg1, src1Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::DeInterleave(dstReg0, dstReg1, srcReg0, srcReg1);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dst0Addr + i * oneRepeatSize, dstReg0, mask);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dst1Addr + i * oneRepeatSize, dstReg1, mask);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,17)])])}const _=t(d,[["render",r]]);export{R as __pageData,_ as default};
